/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type WebsiteSpeedProps = Record<string, any>;

const WebsiteSpeed: React.FC<WebsiteSpeedProps> = ({
  backgroundColor = "#09090b",
  transparentBackground = false,
  durationInSeconds = 6,
  title = "Optimización de Velocidad",
  subtitle = "Mejora el tiempo de carga y el rendimiento de tu sitio web. Cada milisegundo cuenta para una experiencia de usuario fluida y conversiones exitosas.",
  primaryColor = "#3b82f6", // Blue
  accentColor = "#10b981", // Emerald Green
  finalScore = 98,
  barCount = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Core layout metrics
  const safeZone = width * 0.08;
  const contentWidth = width - safeZone * 2;
  const leftColWidth = contentWidth * 0.45;
  const rightColWidth = contentWidth * 0.45;
  const chartHeight = height * 0.5;

  // Background handling
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animations ---
  
  // Grid background speed effect
  const gridOffset = interpolate(frame, [0, fps * durationInSeconds], [0, 400]);

  // Text Entrance
  const titleOpacity = interpolate(frame, [5, 25], [0, 1], { extrapolateRight: "clamp" });
  const titleY = interpolate(frame, [5, 25], [30, 0], { easing: Easing.out(Easing.cubic), extrapolateRight: "clamp" });
  
  const subOpacity = interpolate(frame, [15, 35], [0, 1], { extrapolateRight: "clamp" });
  const subY = interpolate(frame, [15, 35], [30, 0], { easing: Easing.out(Easing.cubic), extrapolateRight: "clamp" });

  // Score & Radial Progress
  const scoreStartFrame = 20;
  const scoreDuration = 60;
  const currentScore = interpolate(
    frame,
    [scoreStartFrame, scoreStartFrame + scoreDuration],
    [0, finalScore],
    { easing: Easing.out(Easing.bezier(0.22, 1, 0.36, 1)), extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const radius = 120;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (currentScore / 100) * circumference;
  
  const scoreScale = spring({
    fps,
    frame: frame - scoreStartFrame,
    config: { damping: 12, stiffness: 100 },
  });

  // Chart Generation (Deterministic upward trend)
  const barSpacing = rightColWidth / barCount;
  const barWidth = barSpacing * 0.5;
  
  const bars = Array.from({ length: barCount }).map((_, i) => {
    // Generate an exponentially increasing height for the "increasing speed" visual
    const progressRatio = i / (barCount - 1); // 0 to 1
    const normalizedHeight = 0.2 + 0.8 * Math.pow(progressRatio, 1.5);
    const targetHeight = chartHeight * normalizedHeight;
    
    const barDelay = 30 + i * 5;
    const barScaleY = spring({
      fps,
      frame: frame - barDelay,
      config: { damping: 14, stiffness: 120 },
    });
    
    return {
      x: i * barSpacing,
      width: barWidth,
      targetHeight,
      currentHeight: targetHeight * barScaleY,
      centerX: i * barSpacing + barWidth / 2,
    };
  });

  // Line Chart Path over bars
  const linePath = bars.reduce((acc, bar, i) => {
    const y = chartHeight - bar.currentHeight;
    if (i === 0) return `M ${bar.centerX} ${y}`;
    return `${acc} L ${bar.centerX} ${y}`;
  }, "");

  const lineDrawProgress = interpolate(
    frame,
    [40, 40 + barCount * 5 + 20], // Matches the stagger of the bars
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  
  // Approx line length for dash array
  const pathLength = rightColWidth * 1.5; 
  const lineDashoffset = pathLength - lineDrawProgress * pathLength;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      
      {/* Moving Speed Grid Background */}
      <svg style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", opacity: 0.1 }}>
        <defs>
          <pattern id="speedGrid" width="60" height="60" patternUnits="userSpaceOnUse" x={gridOffset}>
            <path d="M 60 0 L 0 0 0 60" fill="none" stroke={primaryColor} strokeWidth="1" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#speedGrid)" />
      </svg>

      {/* Main Content Layout */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "center",
          padding: safeZone,
          width: "100%",
          height: "100%",
          boxSizing: "border-box",
        }}
      >
        {/* LEFT COLUMN: Text & Score */}
        <div style={{ width: leftColWidth, display: "flex", flexDirection: "column", gap: "40px" }}>
          
          {/* Text Content */}
          <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
            <h1
              style={{
                fontSize: "72px",
                fontWeight: 800,
                color: "#ffffff",
                margin: 0,
                lineHeight: 1.1,
                opacity: titleOpacity,
                transform: `translateY(${titleY}px)`,
                letterSpacing: "-0.02em",
                transition: "none",
              }}
            >
              {title}
            </h1>
            <p
              style={{
                fontSize: "28px",
                fontWeight: 400,
                color: "#94a3b8",
                margin: 0,
                lineHeight: 1.5,
                opacity: subOpacity,
                transform: `translateY(${subY}px)`,
                maxWidth: "90%",
                transition: "none",
              }}
            >
              {subtitle}
            </p>
          </div>

          {/* Speed Score Indicator */}
          <div
            style={{
              position: "relative",
              width: "280px",
              height: "280px",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              transform: `scale(${scoreScale})`,
              transition: "none",
            }}
          >
            {/* SVG Radial Progress */}
            <svg width="280" height="280" style={{ position: "absolute", transform: "rotate(-90deg)" }}>
              {/* Background Track */}
              <circle
                cx="140"
                cy="140"
                r={radius}
                fill="none"
                stroke={`${accentColor}33`}
                strokeWidth="24"
                strokeLinecap="round"
              />
              {/* Active Track */}
              <circle
                cx="140"
                cy="140"
                r={radius}
                fill="none"
                stroke={accentColor}
                strokeWidth="24"
                strokeLinecap="round"
                strokeDasharray={circumference}
                strokeDashoffset={strokeDashoffset}
                style={{
                  filter: `drop-shadow(0 0 12px ${accentColor}80)`,
                }}
              />
            </svg>
            {/* Score Text */}
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginTop: "10px" }}>
              <span style={{ fontSize: "72px", fontWeight: 800, color: "#ffffff", lineHeight: 1 }}>
                {Math.round(currentScore)}
              </span>
              <span style={{ fontSize: "20px", fontWeight: 600, color: accentColor, textTransform: "uppercase", letterSpacing: "2px" }}>
                Rendimiento
              </span>
            </div>
          </div>
        </div>

        {/* RIGHT COLUMN: Increasing Graphics / Charts */}
        <div
          style={{
            width: rightColWidth,
            height: chartHeight,
            position: "relative",
            display: "flex",
            alignItems: "flex-end",
          }}
        >
          {/* SVG for Line Chart overlay */}
          <svg
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              overflow: "visible",
              zIndex: 10,
            }}
          >
            <path
              d={linePath}
              fill="none"
              stroke={primaryColor}
              strokeWidth="6"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray={pathLength}
              strokeDashoffset={lineDashoffset}
              style={{
                filter: `drop-shadow(0 8px 16px ${primaryColor}66)`,
              }}
            />
            {/* Data point circles on the line */}
            {bars.map((bar, i) => {
              const pointScale = spring({
                fps,
                frame: frame - (30 + i * 5) - 10, // pop in slightly after bar
                config: { damping: 10 },
              });
              return (
                <circle
                  key={`point-${i}`}
                  cx={bar.centerX}
                  cy={chartHeight - bar.currentHeight}
                  r={8 * pointScale}
                  fill="#ffffff"
                  stroke={primaryColor}
                  strokeWidth="4"
                />
              );
            })}
          </svg>

          {/* Bar Chart HTML Elements */}
          {bars.map((bar, i) => (
            <div
              key={`bar-${i}`}
              style={{
                position: "absolute",
                left: bar.x,
                bottom: 0,
                width: bar.width,
                height: bar.currentHeight,
                backgroundColor: `${primaryColor}22`,
                borderTopLeftRadius: "8px",
                borderTopRightRadius: "8px",
                border: `2px solid ${primaryColor}66`,
                borderBottom: "none",
                boxSizing: "border-box",
                transition: "none",
              }}
            >
              {/* Gradient fill inside bar */}
              <div
                style={{
                  position: "absolute",
                  bottom: 0,
                  left: 0,
                  width: "100%",
                  height: "100%",
                  background: `linear-gradient(to top, ${primaryColor}00, ${primaryColor}80)`,
                  borderTopLeftRadius: "6px",
                  borderTopRightRadius: "6px",
                }}
              />
            </div>
          ))}
          
          {/* Decorative Base Line */}
          <div
            style={{
              position: "absolute",
              bottom: 0,
              left: 0,
              width: "100%",
              height: "2px",
              backgroundColor: `${primaryColor}40`,
              zIndex: 0,
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default WebsiteSpeed;